/// <reference path="../pb_data/types.d.ts" />

// Deploy-time mail configuration.
//
// The public site URL and the SMTP transport are deployment facts, not source
// facts. The first settings migration baked in a preview host
// ("…app-preview.com/hcgi/platform"), so every link generated by a hook — and
// every PocketBase verification mail — pointed at a domain that does not serve
// LARAS. Read both from the environment here and leave the stored value alone
// when the variable is absent, so `docker compose up` stays reproducible and a
// local instance keeps its own settings.
migrate(
	(app) => {
		const settings = app.settings();

		const appUrl = ($os.getenv("PUBLIC_APP_URL") || "").trim().replace(/\/+$/, "");
		if (appUrl) {
			settings.meta.appURL = appUrl;
		}

		const smtpHost = ($os.getenv("SMTP_HOST") || "").trim();
		let senderFrom = "";
		if (smtpHost) {
			const port = parseInt($os.getenv("SMTP_PORT") || "587", 10);
			settings.smtp.enabled = true;
			settings.smtp.host = smtpHost;
			settings.smtp.port = isNaN(port) ? 587 : port;
			settings.smtp.username = $os.getenv("SMTP_USERNAME") || "";
			settings.smtp.password = $os.getenv("SMTP_PASSWORD") || "";
			settings.smtp.authMethod = $os.getenv("SMTP_AUTH_METHOD") || "PLAIN";
			settings.smtp.tls = ($os.getenv("SMTP_TLS") || "true") !== "false";
			// Without an envelope sender the mail goes out as MAIL FROM:<> and
			// strict providers reject or spam-file it.
			senderFrom =
				($os.getenv("SMTP_FROM") || "").trim() ||
				(settings.meta.senderAddress || "").trim() ||
				settings.smtp.username;
		}
		if (senderFrom) {
			settings.meta.senderAddress = senderFrom;
		}
		if (!settings.meta.senderName) {
			settings.meta.senderName = "LARAS";
		}

		if (appUrl || smtpHost) {
			app.save(settings);
		}
	},
	(app) => {
		// Settings are operational data; a rollback must not silently change
		// which host sends mail or where links point.
	},
);